ValidationRule.errorConditionFormula:
/* Bloque toute modification de Status__c par les utilisateurs ciblés
   SAUF la transition "Sent to customer" --> "Ordered by customer" */

AND(
  ISCHANGED(Status__c),
  $Permission.CanConfirmOrder,
  NOT(
    AND(
      TEXT(PRIORVALUE(Status__c)) = "Sent to customer",
      TEXT(Status__c) = "Ordered by customer"
    )
  )
)
